CREATE TYPE public.app_role AS ENUM ('admin','teacher','student');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
ALTER TABLE public.profiles ADD COLUMN target_exam text NOT NULL DEFAULT 'ENEM', ADD COLUMN target_university text NOT NULL DEFAULT '', ADD COLUMN notifications_enabled boolean NOT NULL DEFAULT true, ADD COLUMN ranking_opt_in boolean NOT NULL DEFAULT false;
CREATE TABLE public.academic_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('question','content','theme','exam')), title text NOT NULL, exam text NOT NULL DEFAULT 'ENEM' CHECK(exam IN ('ENEM','FUVEST','Unicamp')), subject text NOT NULL DEFAULT '', topic text NOT NULL DEFAULT '', difficulty integer NOT NULL DEFAULT 3 CHECK(difficulty BETWEEN 1 AND 5), statement text NOT NULL DEFAULT '', choices jsonb NOT NULL DEFAULT '[]', correct_key text, explanation text NOT NULL DEFAULT '', source_url text NOT NULL DEFAULT '', source_year integer, origin text NOT NULL DEFAULT 'authorial' CHECK(origin IN ('authorial','official','ai_review')), published boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.academic_items TO authenticated;
GRANT ALL ON public.academic_items TO service_role;
ALTER TABLE public.academic_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY items_admin_read ON public.academic_items FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, mode text NOT NULL CHECK(mode IN ('diagnostic','daily','exam')), exam text NOT NULL, item_ids uuid[] NOT NULL, current_index integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'in_progress' CHECK(status IN ('in_progress','completed')), score numeric, score_by_topic jsonb NOT NULL DEFAULT '{}', target_course text NOT NULL DEFAULT '', target_university text NOT NULL DEFAULT '', started_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, completed_at timestamptz);
GRANT SELECT ON public.academic_sessions TO authenticated;
GRANT ALL ON public.academic_sessions TO service_role;
ALTER TABLE public.academic_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY sessions_read ON public.academic_sessions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_responses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, session_id uuid NOT NULL REFERENCES public.academic_sessions(id) ON DELETE CASCADE, item_id uuid NOT NULL REFERENCES public.academic_items(id), selected_key text NOT NULL, is_correct boolean NOT NULL, answered_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session_id,item_id));
GRANT SELECT ON public.academic_responses TO authenticated;
GRANT ALL ON public.academic_responses TO service_role;
ALTER TABLE public.academic_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY responses_read ON public.academic_responses FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, item_id uuid NOT NULL REFERENCES public.academic_items(id) ON DELETE CASCADE, completed boolean NOT NULL DEFAULT false, rating numeric NOT NULL DEFAULT 1000, due_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,item_id));
GRANT SELECT ON public.academic_progress TO authenticated;
GRANT ALL ON public.academic_progress TO service_role;
ALTER TABLE public.academic_progress ENABLE ROW LEVEL SECURITY;
CREATE POLICY progress_read ON public.academic_progress FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.academic_entitlements (user_id uuid PRIMARY KEY, pro_until timestamptz, human_credits integer NOT NULL DEFAULT 0 CHECK(human_credits>=0), subscription_status text NOT NULL DEFAULT 'free');
GRANT SELECT ON public.academic_entitlements TO authenticated;
GRANT ALL ON public.academic_entitlements TO service_role;
ALTER TABLE public.academic_entitlements ENABLE ROW LEVEL SECURITY;
CREATE POLICY entitlement_read ON public.academic_entitlements FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_evaluations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, essay_id uuid NOT NULL REFERENCES public.essays(id) ON DELETE CASCADE, exam text NOT NULL CHECK(exam IN ('ENEM','FUVEST','Unicamp')), essay_snapshot jsonb NOT NULL, type text NOT NULL DEFAULT 'ai' CHECK(type IN ('ai','human')), status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','completed','failed')), feedback jsonb, error_message text, assigned_to uuid, due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
GRANT SELECT ON public.academic_evaluations TO authenticated;
GRANT ALL ON public.academic_evaluations TO service_role;
ALTER TABLE public.academic_evaluations ENABLE ROW LEVEL SECURITY;
CREATE POLICY evaluation_read ON public.academic_evaluations FOR SELECT TO authenticated USING(user_id=auth.uid() OR assigned_to=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, body text NOT NULL DEFAULT '', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.academic_notifications TO authenticated;
GRANT ALL ON public.academic_notifications TO service_role;
ALTER TABLE public.academic_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notification_read ON public.academic_notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.academic_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, kind text NOT NULL CHECK(kind IN ('deletion','human_credit','subscription')), status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.academic_requests TO authenticated;
GRANT ALL ON public.academic_requests TO service_role;
ALTER TABLE public.academic_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY requests_read ON public.academic_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.academic_ai_state (id text PRIMARY KEY DEFAULT 'global', paused boolean NOT NULL DEFAULT false, reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.academic_ai_state TO service_role;
ALTER TABLE public.academic_ai_state ENABLE ROW LEVEL SECURITY;
CREATE INDEX academic_sessions_owner ON public.academic_sessions(user_id,started_at DESC);
CREATE INDEX academic_eval_owner ON public.academic_evaluations(user_id,created_at DESC);
CREATE INDEX academic_items_exam ON public.academic_items(exam,kind,published);
CREATE INDEX academic_responses_owner ON public.academic_responses(user_id,answered_at DESC);
CREATE FUNCTION public.academic_reserve_evaluation(p_user uuid,p_essay uuid,p_exam text,p_type text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.essays; entitlement public.academic_entitlements; result uuid; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,0));
SELECT * INTO e FROM public.essays WHERE id=p_essay AND user_id=p_user;
IF NOT FOUND THEN RAISE EXCEPTION 'Redação não encontrada.'; END IF;
IF p_exam NOT IN ('ENEM','FUVEST','Unicamp') OR p_type NOT IN ('ai','human') THEN RAISE EXCEPTION 'Avaliação inválida.'; END IF;
IF EXISTS(SELECT 1 FROM public.academic_evaluations WHERE essay_id=p_essay AND status IN ('queued','running')) THEN RAISE EXCEPTION 'Já existe uma correção em andamento.'; END IF;
SELECT * INTO entitlement FROM public.academic_entitlements WHERE user_id=p_user;
IF p_type='ai' AND COALESCE(entitlement.pro_until>now(),false)=false AND (SELECT count(*) FROM public.academic_evaluations WHERE user_id=p_user AND type='ai' AND status<>'failed' AND created_at>=date_trunc('month',now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo')>=1 THEN RAISE EXCEPTION 'O plano gratuito permite uma correção por IA por mês.'; END IF;
IF p_type='human' THEN UPDATE public.academic_entitlements SET human_credits=human_credits-1 WHERE user_id=p_user AND human_credits>0; IF NOT FOUND THEN RAISE EXCEPTION 'Você precisa de um crédito para correção humana.'; END IF; END IF;
INSERT INTO public.academic_evaluations(user_id,essay_id,exam,essay_snapshot,type,due_at) VALUES(p_user,p_essay,p_exam,jsonb_build_object('title',e.title,'theme',e.theme,'content',e.content),p_type,CASE WHEN p_type='human' THEN now()+interval '72 hours' ELSE NULL END) RETURNING id INTO result;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.academic_reserve_evaluation(uuid,uuid,text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.academic_reserve_evaluation(uuid,uuid,text,text) TO service_role;
CREATE FUNCTION public.academic_create_session(p_user uuid,p_mode text,p_exam text,p_ids uuid[],p_course text,p_university text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; used integer; is_pro boolean; BEGIN
PERFORM pg_advisory_xact_lock(hashtextextended(p_user::text,0));
IF p_mode NOT IN ('diagnostic','daily','exam') OR p_exam NOT IN ('ENEM','FUVEST','Unicamp') OR cardinality(p_ids)=0 THEN RAISE EXCEPTION 'Sessão inválida.'; END IF;
IF EXISTS(SELECT 1 FROM public.academic_items i WHERE i.id=ANY(p_ids) AND (i.kind<>'question' OR NOT i.published OR i.exam<>p_exam)) OR (SELECT count(*) FROM public.academic_items WHERE id=ANY(p_ids))<>cardinality(p_ids) THEN RAISE EXCEPTION 'Questões inválidas.'; END IF;
IF p_mode='daily' THEN
SELECT COALESCE(sum(cardinality(item_ids)),0) INTO used FROM public.academic_sessions WHERE user_id=p_user AND mode='daily' AND started_at >= date_trunc('day',now() AT TIME ZONE 'America/Sao_Paulo') AT TIME ZONE 'America/Sao_Paulo';
SELECT COALESCE(pro_until>now(),false) INTO is_pro FROM public.academic_entitlements WHERE user_id=p_user;
IF NOT COALESCE(is_pro,false) AND used+cardinality(p_ids)>20 THEN RAISE EXCEPTION 'O plano gratuito permite até 20 questões diárias.'; END IF;
END IF;
INSERT INTO public.academic_sessions(user_id,mode,exam,item_ids,target_course,target_university,expires_at) VALUES(p_user,p_mode,p_exam,p_ids,p_course,p_university,CASE WHEN p_mode='exam' THEN now()+interval '60 minutes' ELSE NULL END) RETURNING id INTO result;
RETURN result; END $$;
REVOKE ALL ON FUNCTION public.academic_create_session(uuid,text,text,uuid[],text,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.academic_create_session(uuid,text,text,uuid[],text,text) TO service_role;